#!/usr/bin/env python3
"""读取 CSV 文件，统计每一列的非空值数量。

用法:
    python csv_nonempty_counts.py <csv文件> [--encoding utf-8]
"""

import argparse
import csv
import sys


def count_nonempty(path: str, encoding: str = "utf-8") -> tuple[list[str], dict[str, int]]:
    headers: list[str] = []
    counts: dict[str, int] = {}

    with open(path, newline="", encoding=encoding) as f:
        reader = csv.reader(f)
        try:
            headers = next(reader)
        except StopIteration:
            return headers, counts

        names = [h.strip() or f"column_{i + 1}" for i, h in enumerate(headers)]
        counts = {name: 0 for name in names}

        for row in reader:
            for i, value in enumerate(row[: len(names)]):
                if value.strip():
                    counts[names[i]] += 1

    return headers, counts


def main() -> int:
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--encoding", default="utf-8-sig", help="文件编码，默认 utf-8-sig")
    args = parser.parse_args()

    try:
        headers, counts = count_nonempty(args.csv_file, args.encoding)
    except FileNotFoundError:
        print(f"错误: 文件不存在: {args.csv_file}", file=sys.stderr)
        return 1

    if not counts:
        print("文件为空，没有可统计的列。")
        return 0

    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name:<{width}}  {count}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
